public class JitWarmupDemo {
    public static void computeIntensiveTask() {
        long sum = 0;
        // A hot loop triggers JIT compilation backedge counters
        for (int i = 0; i < 100_000_000; i++) {
            sum += (i * 3) ^ (i >> 2);
        }
    }

    public static void main(String[] args) {
        // Warmup phase: allows JIT to compile the hot method
        for (int i = 0; i < 50; i++) {
            computeIntensiveTask();
        }
    }
}
